window.renderHeft = function(h, steps){
  var st = steps ? ' step' : '', out = '';
  var svg = h.blocks.filter(function(b){ return b.t==='svg'; })[0];
  out += '<div class="hb-wrap'+(svg?' has-svg':'')+'"><div class="hb-main">';
  h.blocks.forEach(function(b){
    if(b.t==='svg') return;
    if(b.t==='merk') out += '<div class="hmerk'+st+'"><span class="auf abschreiben">Abschreiben</span>'+b.html+'</div>';
    else if(b.t==='rule') out += '<div class="hrule-l'+st+'">'+b.html+'</div>';
    else if(b.t==='ex') out += '<div class="hex'+st+'"><span class="auf beispiel">Beispiel ins Heft</span>'+b.html+'</div>';
    else if(b.t==='law') out += '<div class="hlaw'+st+'"><b>'+b.name+'</b><div>'+b.html+'</div><div class="lex">'+b.ex+'</div></div>';
    else if(b.t==='stairs') out += '<div class="hstairs2'+st+'">'+b.html.map(function(x,i){ return '<span class="hs s'+(i+1)+'"><i>'+(i+1)+'</i>'+x+'</span>'; }).join('')+'</div>';
  });
  out += '</div>';
  if(svg) out += '<div class="hb-svg'+st+'">'+svg.html+'</div>';
  return out + '</div>';
};
